SELECT 'ctr_uz_time-management', "id", 'uz', 'Taym-menejment: asosiy tamoyillar', 'Ustuvorliklar, maqsadlar va vaqtni boshqarish vositalari — Vitaliy Dubovik treningi', 'Biznes-trener Vitaliy Dubovikdan (activesales.by) taym-menejment bo''yicha amaliy videokurs. 18 dars — bazaviy tamoyillardan tayyor vositalargacha: Eyzenxauer matritsasi bo''yicha ustuvorliklarni qanday belgilash, kunni 60/40 qoidasi bilan rejalashtirish, «baqadan» boshlash, yirik vazifalarni «fil» va «uch mix» texnikasi bilan bo''lish, maqsadni to''g''ri qo''yish, kundalik va Google Kalendarni yuritish, xronometraj orqali «vaqt yeguvchilarni» topish hamda ofisda ham, masofadan ham samarali ishni tashkil qilish. Material B2B''dagi jonli treninglarda suratga olingan, lekin barcha modellar universal.', NOW()
FROM "Course" WHERE "slug" = 'time-management'
